// ─── HELPERS ────────────────────────────────────────────
const QT_FORMAT = v => typeof v === 'number' ? v.toFixed(2) : '—';
const QT_CONFIDENCE_COLOR = v => v >= 0.9 ? C.green500 : v >= 0.7 ? C.orange500 : C.red500;

// ─── REGRAS SIMPLIFICADAS (P1=A) ──────────────────────
const QT_PE_DIREITO = 2.8; // pé direito padrão
const QT_CALC_RULES = [{
  label: 'Piso',
  un: 'm²',
  calc: r => r.area_m2 * 1.10,
  desc: 'Área + 10% perda'
}, {
  label: 'Contrapiso',
  un: 'm²',
  calc: r => r.area_m2 * 1.05,
  desc: 'Área + 5% perda'
}, {
  label: 'Parede (alvenaria)',
  un: 'm²',
  calc: r => r.perimeter_m * QT_PE_DIREITO,
  desc: 'Perímetro × pé direito 2.80m'
}, {
  label: 'Reboco interno',
  un: 'm²',
  calc: r => r.perimeter_m * QT_PE_DIREITO * 2,
  desc: 'Parede × 2 faces'
}, {
  label: 'Teto (laje)',
  un: 'm²',
  calc: r => r.area_m2,
  desc: 'Área do teto'
}, {
  label: 'Rodapé',
  un: 'm',
  calc: r => r.perimeter_m * 0.85,
  desc: 'Perímetro − vãos (15%)'
}];

